 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)

    # Solid non-background lines partition the canvas into equal-sized panels.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1])
                 for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1])
                 for i in range(len(col_bounds) - 1)]
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors |= {grid[0][c] for c in sep_cols}

    # The populated panel is the template; repeat its contents in panels
    # having matching dimensions while leaving the solid dividers intact.
    panels = []
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            marks = [(dr, dc, grid[r0 + dr][c0 + dc])
                     for dr in range(r1 - r0)
                     for dc in range(c1 - c0)
                     if grid[r0 + dr][c0 + dc] != bg
                     and grid[r0 + dr][c0 + dc] not in separator_colors]
            panels.append((len(marks), ri, ci, marks))
    _, sri, sci, motif = max(panels, key=lambda item: item[0])
    sr0, sr1 = row_spans[sri]
    sc0, sc1 = col_spans[sci]
    sh, sw = sr1 - sr0, sc1 - sc0

    out = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1 - r0 != sh or c1 - c0 != sw:
                continue
            for dr in range(sh):
                for dc in range(sw):
                    out[r0 + dr][c0 + dc] = bg
            for dr, dc, value in motif:
                out[r0 + dr][c0 + dc] = value
    return out
